const colorRanks = { 'Red': 1, 'Orange': 2, 'Yellow': 3, 'Yellow-White': 4, 'White': 5, 'Blue-White': 6 };

function computeSimilarity(s1, s2) {
  if (s1 === s2) return { total: 100, sSize: 100, sTemp: 100, sColor: 100, sBright: 100, sComp: 100, sStage: 100 };
  const d1 = starTraits[s1];
  const d2 = starTraits[s2];
  if (!d1 || !d2) return { total: 0, sSize: 0, sTemp: 0, sColor: 0, sBright: 0, sComp: 0, sStage: 0 };

  const sSize = Math.max(0, 1 - Math.abs(Math.log10((d1.size || 0.01) / (d2.size || 0.01))) / 2) * 100;
  const maxTemp = Math.max(d1.temp, d2.temp) || 5000;
  const sTemp = Math.max(0, 1 - Math.abs(d1.temp - d2.temp) / maxTemp) * 100;
  const stepDiff = Math.abs((colorRanks[d1.color] || 3) - (colorRanks[d2.color] || 3));
  const sColor = Math.max(0, 1 - stepDiff / 5) * 100;
  const b1 = Math.max(0.00001, d1.brightness);
  const b2 = Math.max(0.00001, d2.brightness);
  const sBright = Math.max(0, 1 - Math.abs(Math.log10(b1 / b2)) / 5) * 100;
  const sComp = Math.max(0, 1 - Math.abs(d1.compVal - d2.compVal) / 2) * 100;

  let sStage = 20;
  if (d1.stage === d2.stage) sStage = 100;
  else if (d1.stage.includes('Main Sequence') && d2.stage.includes('Main Sequence')) sStage = 80;
  else if (d1.stage.includes('Sub') || d2.stage.includes('Sub')) sStage = 50;

  const total = Math.round((sSize + sTemp + sColor + sBright + sComp + sStage) / 6);
  return { total, sSize: Math.round(sSize), sTemp: Math.round(sTemp), sColor: Math.round(sColor), sBright: Math.round(sBright), sComp: Math.round(sComp), sStage: Math.round(sStage) };
}

function explainRelationship(refStar, targetStar, isSimilar, score) {
  const d1 = starTraits[refStar];
  const d2 = starTraits[targetStar];
  if (!d1 || !d2) return '';

  const reasons = [];

  // Temperature & Color
  const tempDiff = Math.abs(d1.temp - d2.temp);
  if (tempDiff < 600) {
    reasons.push('<li><strong>🌡️ Temperature & Color (' + d1.color + '):</strong> Nearly identical surface temperature (' + d1.temp.toLocaleString() + ' K vs ' + d2.temp.toLocaleString() + ' K), radiating the same ' + d1.color.toLowerCase() + ' glow.</li>');
  } else {
    reasons.push('<li><strong>🌡️ Temperature & Color:</strong> Drastic temperature contrast of ' + tempDiff.toLocaleString() + ' K (' + d1.temp.toLocaleString() + ' K ' + d1.color + ' vs ' + d2.temp.toLocaleString() + ' K ' + d2.color + ').</li>');
  }

  // Size
  const sizeRatio = Math.max(d1.size, d2.size) / Math.max(0.001, Math.min(d1.size, d2.size));
  if (sizeRatio < 1.4) {
    reasons.push('<li><strong>📐 Physical Size:</strong> Extremely close physical dimensions (' + d1.size + ' R☉ vs ' + d2.size + ' R☉).</li>');
  } else {
    reasons.push('<li><strong>📐 Physical Size:</strong> Massive size disparity (' + d1.size + ' R☉ vs ' + d2.size + ' R☉, a ' + sizeRatio.toFixed(1) + 'x difference).</li>');
  }

  // Brightness
  const bRatio = Math.max(d1.brightness, d2.brightness) / Math.max(0.00001, Math.min(d1.brightness, d2.brightness));
  if (bRatio < 2.5) {
    reasons.push('<li><strong>💡 Luminosity:</strong> Very similar radiant energy output (' + d1.brightness + ' L☉ vs ' + d2.brightness + ' L☉).</li>');
  } else {
    reasons.push('<li><strong>💡 Luminosity:</strong> Huge brightness gulf: one shines ' + Math.round(bRatio).toLocaleString() + 'x more powerfully than the other (' + d1.brightness + ' L☉ vs ' + d2.brightness + ' L☉).</li>');
  }

  // Atmosphere
  if (d1.atmosphere && d2.atmosphere) {
    if (d1.color === d2.color) {
      reasons.push('<li><strong>☀️ Stellar Atmosphere:</strong> Both possess similar atmospheric layers and elemental composition: ' + d2.atmosphere.split('.')[0] + '.</li>');
    } else {
      reasons.push('<li><strong>☀️ Stellar Atmosphere Contrast:</strong> <em>' + targetStar + '</em> has: ' + d2.atmosphere.split('.')[0] + ', contrasting with <em>' + refStar + '</em>.</li>');
    }
  }

  // Life Stage
  if (d1.stage === d2.stage) {
    reasons.push('<li><strong>⏳ Life Cycle Stage:</strong> Both reside in the exact same stellar phase: <em>' + d1.stage + '</em>.</li>');
  } else {
    reasons.push('<li><strong>⏳ Life Cycle Stage:</strong> Opposite evolutionary phases: <em>' + d1.stage + '</em> vs. <em>' + d2.stage + '</em>.</li>');
  }

  const badgeColor = isSimilar ? '#2e7d32' : '#c62828';
  const badgeBg = isSimilar ? '#e8f5e9' : '#ffebee';
  const label = isSimilar ? 'Highly Similar (' + score + '% Match)' : 'Highly Dissimilar (' + score + '% Match / ' + (100 - score) + '% Divergence)';

  return '<div style="display: flex; gap: 16px; align-items: flex-start; flex-wrap: wrap;">' +
    '<img src="' + d2.image + '" alt="' + targetStar + '" style="width: 140px; height: 140px; object-fit: cover; border-radius: 8px; box-shadow: 0 3px 6px rgba(0,0,0,0.15);">' +
    '<div style="flex: 1; min-width: 250px;">' +
      '<div style="display: inline-block; padding: 4px 10px; background: ' + badgeBg + '; color: ' + badgeColor + '; border-radius: 4px; font-weight: bold; font-size: 13px; margin-bottom: 6px;">' + label + '</div>' +
      '<h4 style="margin: 0 0 8px 0; color: navy;">' + targetStar + ' compared to ' + refStar + '</h4>' +
      '<ul style="margin: 0; padding-left: 20px; line-height: 1.6; font-size: 14px;">' +
        reasons.join('') +
      '</ul>' +
    '</div>' +
  '</div>';
}

function updateSimilarityGallery() {
  const sel1 = document.getElementById('ref-star-select').value;
  if (!sel1 || !starTraits[sel1]) return;

  const allNames = Object.keys(starTraits);
  const scored = [];

  for (let i = 0; i < allNames.length; i++) {
    const n = allNames[i];
    if (n !== sel1) {
      scored.push({ name: n, score: computeSimilarity(sel1, n).total });
    }
  }

  scored.sort((a, b) => b.score - a.score);

  // Pick top 4 most similar and top 4 most dissimilar
  const mostSimilar = scored.slice(0, 4);
  const mostDissimilar = scored.slice(-4).reverse();

  // Render Similar Cards (only pictures and names)
  const simContainer = document.getElementById('similar-stars-grid');
  if (simContainer) {
    simContainer.innerHTML = '';
    mostSimilar.forEach((item, idx) => {
      const data = starTraits[item.name];
      const card = document.createElement('div');
      card.className = 'star-thumb-card';
      card.style.cssText = 'cursor: pointer; text-align: center; border-radius: 8px; padding: 8px; background: #ffffff; border: 2px solid #e0e0e0; transition: transform 0.2s, border-color 0.2s; max-width: 135px; flex: 1; min-width: 110px;';
      card.innerHTML = '<img src="' + data.image + '" alt="' + item.name + '" style="width: 100%; height: 95px; object-fit: cover; border-radius: 6px;">' +
        '<div style="font-weight: bold; font-size: 13px; margin-top: 6px; color: #1a237e; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">' + item.name + '</div>';

      card.onmouseover = () => { card.style.borderColor = '#2e7d32'; card.style.transform = 'translateY(-3px)'; };
      card.onmouseout = () => { if (!card.classList.contains('active-card')) { card.style.borderColor = '#e0e0e0'; card.style.transform = 'none'; } };
      card.onclick = () => {
        document.querySelectorAll('.star-thumb-card').forEach(c => { c.classList.remove('active-card'); c.style.borderColor = '#e0e0e0'; c.style.transform = 'none'; });
        card.classList.add('active-card');
        card.style.borderColor = '#2e7d32';
        card.style.transform = 'translateY(-3px)';
        const expEl = document.getElementById('similarity-explanation-box');
        if (expEl) expEl.innerHTML = explainRelationship(sel1, item.name, true, item.score);
      };

      // Automatically select first similar star by default
      if (idx === 0) {
        card.classList.add('active-card');
        card.style.borderColor = '#2e7d32';
        const expEl = document.getElementById('similarity-explanation-box');
        if (expEl) expEl.innerHTML = explainRelationship(sel1, item.name, true, item.score);
      }

      simContainer.appendChild(card);
    });
  }

  // Render Dissimilar Cards (only pictures and names)
  const disContainer = document.getElementById('dissimilar-stars-grid');
  if (disContainer) {
    disContainer.innerHTML = '';
    mostDissimilar.forEach(item => {
      const data = starTraits[item.name];
      const card = document.createElement('div');
      card.className = 'star-thumb-card';
      card.style.cssText = 'cursor: pointer; text-align: center; border-radius: 8px; padding: 8px; background: #ffffff; border: 2px solid #e0e0e0; transition: transform 0.2s, border-color 0.2s; max-width: 135px; flex: 1; min-width: 110px;';
      card.innerHTML = '<img src="' + data.image + '" alt="' + item.name + '" style="width: 100%; height: 95px; object-fit: cover; border-radius: 6px;">' +
        '<div style="font-weight: bold; font-size: 13px; margin-top: 6px; color: #b71c1c; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">' + item.name + '</div>';

      card.onmouseover = () => { card.style.borderColor = '#c62828'; card.style.transform = 'translateY(-3px)'; };
      card.onmouseout = () => { if (!card.classList.contains('active-card')) { card.style.borderColor = '#e0e0e0'; card.style.transform = 'none'; } };
      card.onclick = () => {
        document.querySelectorAll('.star-thumb-card').forEach(c => { c.classList.remove('active-card'); c.style.borderColor = '#e0e0e0'; c.style.transform = 'none'; });
        card.classList.add('active-card');
        card.style.borderColor = '#c62828';
        card.style.transform = 'translateY(-3px)';
        const expEl = document.getElementById('similarity-explanation-box');
        if (expEl) expEl.innerHTML = explainRelationship(sel1, item.name, false, item.score);
      };

      disContainer.appendChild(card);
    });
  }
}

function initSimilarityGallery() {
  const sel = document.getElementById('ref-star-select');
  if (!sel) return;

  sel.innerHTML = '';
  const names = Object.keys(starTraits);
  names.forEach((name, i) => {
    const opt = document.createElement('option');
    opt.value = name;
    opt.textContent = name;
    if (name === 'Earth (Sun)') opt.selected = true;
    sel.appendChild(opt);
  });

  sel.addEventListener('change', updateSimilarityGallery);
  updateSimilarityGallery();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initSimilarityGallery);
} else {
  initSimilarityGallery();
}
